// Flap — Adw.Flap
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles flap with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"
import type { FlapFoldPolicy, FlapTransitionType, FoldThresholdPolicy, PackType } from "@/lib/enums"

export interface FlapProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** Gtk.Widget, from Adw.Flap */
  content?: ReactNode

  /** Gtk.Widget, from Adw.Flap */
  flap?: ReactNode

  /** Gtk.PackType, from Adw.Flap */
  flapPosition?: PackType

  /** guint, from Adw.Flap */
  foldDuration?: number

  /** FlapFoldPolicy, from Adw.Flap */
  foldPolicy?: FlapFoldPolicy

  /** FoldThresholdPolicy, from Adw.Flap */
  foldThresholdPolicy?: FoldThresholdPolicy

  /** gboolean, from Adw.Flap */
  locked?: boolean

  /** gboolean, from Adw.Flap */
  modal?: boolean

  /** gboolean, from Adw.Flap */
  revealFlap?: boolean

  /** SpringParams, from Adw.Flap */
  revealParams?: ReactNode

  /** Gtk.Widget, from Adw.Flap */
  separator?: ReactNode

  /** gboolean, from Adw.Flap */
  swipeToClose?: boolean

  /** gboolean, from Adw.Flap */
  swipeToOpen?: boolean

  /** FlapTransitionType, from Adw.Flap */
  transitionType?: FlapTransitionType
}

export function Flap({ className, children }: FlapProps) {
  return (
    <div className={cn(className)}>
      {children}
    </div>
  )
}
